func() {
		defer close(resultChan)

		bus.mutex.RLock()
		handlers := bus.handlers[msg.Type()]
		bus.mutex.RUnlock()

		if len(handlers) == 0 {
			// 发送错误消息
			errorMsg := &ErrorMessage{
				BaseMessage: NewBaseMessage(MSG_ERROR, msg.SessionID(), nil),
				Code:        1064,
				State:       "42000",
				Message:     fmt.Sprintf("no handlers for message type: %d", msg.Type()),
			}
			resultChan <- errorMsg
			return
		}

		// 依次调用所有处理器
		for _, handler := range handlers {
			if handler.CanHandle(msg.Type()) {
				response, err := handler.HandleMessage(msg)
				if err != nil {
					// 发送错误消息
					errorMsg := &ErrorMessage{
						BaseMessage: NewBaseMessage(MSG_ERROR, msg.SessionID(), nil),
						Code:        1064,
						State:       "42000",
						Message:     err.Error(),
					}
					resultChan <- errorMsg
					return
				}
				if response != nil {
					resultChan <- response
				}
			}
		}
	}

